use crate::types::{LineMetadata,ListType};
#[derive(Debug,Clone,PartialEq,Eq)]pub struct ListPrefix{pub list_type:ListType,pub indent:u8,pub marker_len:usize,pub number:Option<u32>,pub checked:bool}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct EnterResult{pub next_metadata:LineMetadata,pub exits_list:bool,pub next_prefix:String}
pub fn parse_list_prefix(line:&str,tab_width:usize)->Option<ListPrefix>{let w=tab_width.max(1);let mut bytes=0;let mut cols=0;for c in line.chars(){match c{' '=>{bytes+=1;cols+=1},'\t'=>{bytes+=1;cols+=w},_=>break}}let indent=(cols/w).min(5)as u8;let s=&line[bytes..];let(t,len,num,checked)=if s.starts_with("[] "){(ListType::Check,3,None,false)}else if s.starts_with("[x] ")||s.starts_with("[X] "){(ListType::Check,4,None,true)}else if s.starts_with("- ")||s.starts_with("* "){(ListType::Bullet,2,None,false)}else if let Some(dot)=s.find(". "){if dot==0||!s[..dot].chars().all(|c|c.is_ascii_digit()){return None}(ListType::Number,dot+2,Some(s[..dot].parse().ok()?),false)}else{return None};Some(ListPrefix{list_type:t,indent,marker_len:len,number:num,checked})}
pub fn format_number_prefix(n:u32,indent:u8)->String{format!("{}{}. ","    ".repeat(indent as usize),n)}pub fn format_list_prefix(m:&LineMetadata,n:u32)->String{let i="    ".repeat(m.indent as usize);match m.list_type{ListType::None=>String::new(),ListType::Bullet=>format!("{i}- "),ListType::Number=>format!("{i}{n}. "),ListType::Check=>if m.checked{format!("{i}[x] ")}else{format!("{i}[] ")}}}
pub fn handle_enter(line:&str,m:&LineMetadata)->EnterResult{if !m.is_list(){return EnterResult{next_metadata:LineMetadata::default(),exits_list:false,next_prefix:String::new()}}if line.trim().is_empty()&&m.indent==0{return EnterResult{next_metadata:LineMetadata::default(),exits_list:true,next_prefix:String::new()}}let mut next=m.clone();if line.trim().is_empty(){next.indent=next.indent.saturating_sub(1)}EnterResult{next_prefix:format_list_prefix(&next,1),next_metadata:next,exits_list:false}}
pub fn adjust_indent(m:&mut LineMetadata,increase:bool){if increase{m.indent=(m.indent+1).min(LineMetadata::MAX_INDENT)}else{m.indent=m.indent.saturating_sub(1)}}
